INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '01. El retardo Injustificado.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '02. No comunicar la ejecución de la orden recibida al ó a la superior correspondiente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '03. Tomar parte en competencias deportivas, culturales, académicas o artísticas, sin la debida autorización.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '01. No aplicar la medida disciplinaria correspondiente a las faltas que cometan sus subalternos o subalternas.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '02. No informar de manera inmediata a la autoridad militar competente del cometimiento de una falta, cuando no se tenga la facultad para sancionar.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '03. No informar a tiempo a su superior inmediato la imposibilidad de comparecer a la unidad, establecimiento o instalación militar; o a cualquier otro acto del servicio a que estuviese designado o designada, siempre que esta omisión  no ocasione daños irreparables.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '01. Practicar o promover actos o ritos religiosos en la unidad, instalaciones o establecimientos militares, sin la debida autorización por escrito.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '02. No observar en el desempeño del servicio de centinela los procedimientos establecidos en las leyes y reglamentos correspondientes, sin que ello afecte la seguridad de la unidad.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '03. Distraer al centinela durante su servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '04. Permanecer en un establecimiento o instalación militar donde no preste servicio, sin permiso o consentimiento del respectivo comandante o comandanta, jefe o jefa.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '05. Conversar, perturbar o generar ruidos en reuniones o actos del servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '06. Fumar en lugares no autorizados o en presencia del o la superior sin su consentimiento.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '07. Presentarse con uniforme distinto al indicado, en actos sociales o del servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '08. No mostrar a un o una superior que así lo requiera, la boleta de permiso.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '09. No portar los documentos de identidad personal y militar.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '10. Impedir por cualquier medio, la inspección al entrar o salir del establecimiento o instalación militar.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '11. Ingresar a un área de la unidad, establecimiento o instalación militar cuyo acceso este restringido o prohibido.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '12. Incumplir las normas de tránsito en la unidad, establecimiento o instalación militar ');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '13. No observar las normas de educación y de buenas costumbres.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '14. No manifestar los signos exteriores de respeto al superior, en todo lugar y circunstancia.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '15. Ser descuidado o descuidada en su aseo personal o perjudicar el de sus compañeros en todo lugar y circunstancia.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '16. Facilitar a terceros, objetos materiales o equipos que no estén a su cargo o no lo pertenezcan, sin la debida autorización u orden superior.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '17. Ejercer actividades civiles, cargo o función ajena a la profesión militar, sin permiso de la autoridad militar competente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '18. Ser descuidado o descuidada en la conservación de equipos, vehículos, armas, municiones, alojamiento o utensilios que estén a su cargo.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '19. Destruir o dañar bienes pertenecientes o asignados a la Fuerza Armada Nacional Bolivariana, cuando su valor no exceda de cinco unidades tributarias (5 U.T)');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '20. Vestir de civil de manera no acorde con el decoro, respeto y ejemplo que debe representar para la sociedad, un miembro activo de la Fuerza Armada Nacional Bolivariana.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '21. No ser diligente en el cumplimiento de las tareas asignadas.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '22. No presentarse a su superior inmediato al término de una licencia, permiso, reposo médico o comisión.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '23. incumplir las disposiciones reglamentarias para izar o arriar la bandera o insignia de autoridad.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '24. Permitir la permanencia de subalternos o subalternas que no porten el uniforme previsto para una ceremonia, evento, acto oficial o social.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '25. No presentarse el o la militar al inicio de las labores diarias a su jefe inmediato o jefa inmediata, a fin de dar parte de las novedades.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('1', '26. Incumplir las disposiciones establecidas para el uso de uniforme, prendas militares, corte de cabello y presentación personal dentro y fuera de la dependencia militar.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '04. Dejar de cumplir o de hacer cumplir las prescripciones reglamentarias en la esfera de sus atribuciones.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '05. No tomar previsiones dentro de sus facultades ante cualquier novedad que altere el servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '06. Usar pulseras, leontinas, zarcillos, collares, anillos, lentes, gargantillas, calzado o cualquier otro accesorio que altere el uniforme, el porte y marcialidad del o la militar.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '07.  Manifestar disgusto o tibieza en el servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '08.  Formular quejas sin observar los trámites reglamentarios.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '09. Interponer los recursos administrativos omitiendo el procedimiento legalmente establecido.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '10. Desatender cualquier actividad de la unidad, establecimiento o instalación militar o acto de servicio al que haya sido asignado. ');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '11. Dar razones irrespetuosas al o a la superior.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '12. No presentarse en los plazos establecidos en la unidad, establecimiento, instalación militar, o autoridad ante la cual haya sido nombrado o nombrada para empleo o comisión. ');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '13. Eludir el cumplimiento de compromisos de orden moral o legal asumidos expresamente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '14. ingerir bebidas alcohólicas en la vía pública estando uniformado.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '15. Permanecer fuera de la unidad, establecimiento o instalación militar donde preste servicio, en horas laborables, sin permiso del o la superior inmediato.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '16. Solicitar prórroga de un permiso por sí o por intermedio de terceras personas, por cualquier medio; sin causa justificada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '17. Objetar una medida disciplinaria sin observar el procedimiento establecido en la presente Ley.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '18. Conducir vehículos automotores, naves y aeronaves sin tener la documentación, acreditación y permiso vigente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '19. Realizar trabajos técnicos en vehículos, naves o aeronaves militares de uso administrativo o protocolar sin tener las acreditaciones o certificados correspondientes.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '20. No observar las medidas de seguridad previamente establecidas en los actos del servicio dentro o fuera de la unidad.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '21. Destruir o dañar intencionalmente bienes pertenecientes o asignados a la Fuerza Armada Nacional Bolivariana, cuando su valor sea superior a cinco unidades tributarias  (5 U.T.) e inferior a quince unidades tributarias (15 U.T.).');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '22. Perder la credencial de identificación militar, por descuido.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('2', '23. Efectuar modificaciones a la confección original del uniforme militar, que vayan en contra de lo establecido en la normativa respectiva.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '04. Ocultar, encubrir o falsear la verdad en cualquier asunto o acto del servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '05. Fomentar la discordia o la enemistad entre superiores, compañeros, compañeras, subalternos o subalternas.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '06. Ser cómplice o encubridor de una falta contra la disciplina militar cometida por un o una superior, compañero, compañera, subalterno o subalterna.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '07. Maltratar animales.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '08. Valerse del anonimato con el fin de desacreditar u ofender al o a la superior, compañero, compañera, subalterno o subalterno.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '09. Omitir, el o la comandante de unidad o jefe o jefa de la dependencia, o su equivalente, estando en conocimiento de una falta cometida por un subalterno, los procedimientos establecidos para sancionar o poner en conocimiento de dicha situación a la autoridad militar que pueda evaluarla y sancionarla.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '10. Participar, promover o difundir videos, propagandas u otros medios audiovisuales, fotográficos, impresos e informáticos, donde se presenten situaciones que atenten contra la moral y las buenas costumbres.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '11. Permitir que personas privadas de libertad bajo su custodia conserven en su poder objetos que puedan causar daños.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '12. Fraternizar con personas privadas de libertad bajo su custodia.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '13. Ingresar en la unidad, establecimiento o instalación militar donde no preste servicio, fuera del horario establecido o después del toque de silencio, sin la debida autorización.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '14. Participar en hechos contrarios al orden legal establecido, que alteren el orden público y afecten la reputación de la Fuerza Armada Nacional Bolivariana.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '15. Formular quejas infundadas en perjuicio de los o las superiores, compañeros, compañeras, subalternos o subalternas.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '16. Dificultar o impedir al o a la subalterno la presentación de quejas, recursos o novedades.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '17. Destruir o dañar intencionalmente bienes pertenecientes o asignados a la Fuerza Armada Nacional Bolivariana, cuando su valor sea superior a quince unidades tributarias (15 U.T.)');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '18. Facilitar con fines de lucro a terceros, bienes y recursos financieros pertenecientes o asignados a la Fuerza Armada Nacional Bolivariana.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '19. Facilitar armas o municiones pertenecientes o asignadas a la Fuerza Armada Nacional Bolivariana, para un uso distinto al legalmente establecido, sin menoscabo de la responsabilidad penal correspondiente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '20. La arbitrariedad comprobada dentro y fuera de los actos del servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '21. Promover situaciones para no cumplir una orden superior o para retardar su ejecución.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '22. Dejar de cumplir una orden por negligencia.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '23. No presentar los informes requeridos por el o la superior facultado, en el tiempo establecido.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '24. Asumir compromisos utilizando el nombre de la institución sin estar debidamente autorizado.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '25. Solicitar apoyo en nombre de la Fuerza Armada Nacional Bolivariana, en materia de recursos financieros, bienes o servicios, sin estar debidamente autorizado o autorizada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '26. Cambiar el servicio para el cual fue designado o designada sin autorización de lo de la superior competente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '27. Desempeñar servicio o comisión para el cual no ha sido formalmente designado o designada por el o la superior competente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '28. No desempeñar el servido, función o comisión para la cual haya sido formalmente designado o designada, sin causa justificada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '29. Atribuirse la representación de autoridades millares o civiles, sin estar debidamente autorizado o autorizada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '30. Formular reclamos colectivos o atribuirse la representación de militares o civiles.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '31. Utilizar vehículos, naves o aeronaves millares de uso administrativo de la unidad, establecimiento o instalación militar, sin la debida autorización ');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '32. Emplear la coacción para inducir o impedir el trámite de queja o reclamo contra él o la superior, subalterno, subalterna, compañero o compañera.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '33. Solicitar o aceptar dinero, bienes o servicios en contraprestación a actos del servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '34. Utilizar vestuario y prendas miliares en detrimento del decoro militar.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '35. Modificar, alterar, destruir, sustraer o borrar información registrada en equipos o archivos, sin la debida autorización.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '36. Practicar el agiotismo entre militares.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '37. Contraer deudas con superiores, compañeros, compañeras, subalternos o subalternas que afecten la disciplina o el buen desempeño en la unidad.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '38. Practicar actividades comerciales de cualquier tipo dentro o fuera de las instalaciones militares en horario laborable.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '39. Tomar parte en juegos prohibidos formalmente o efectuar apuestas dentro de la unidad, establecimiento o instalación militar.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '40. ingerir bebidas alcohólicas dentro de la unidad, establecimiento o instalación militar, sin autorización de la autoridad competente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '41. Portar armas de fuego orgánicas no asignadas, dentro o fuera de la unidad, establecimiento o instalación millar, sin estar debidamente autorizado o autorizada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '42. Portar armas de fuego no reglamentarias sin el debido permiso emitido por el organismo competente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '43. Accionar armas de fuego por descuido o dispararlas sin necesidad.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '44. Ejecutar toques o hacer señales que alteren el buen servicio, sin orden o autorización del o de la superior. ');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '45. Divulgar noticias o imágenes que den lugar a alarma injustificada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '46. Difundir opiniones, noticias o imágenes en perjuicio de la moral y las buenas costumbres de los millares o civiles.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '47. No observar las normas de respeto a la dignidad y los derechos humanos relacionados con detenidos bajo su custodia. ');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '48. Autorizar visitas a detenidos sin permiso de la autoridad competente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '49. No notificar de manera inmediata a la autoridad militar correspondiente cualquier condición médica que limite o afecte su estado general de salud y el cumplimiento cabal del servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '50. Entrar o salir de la unidad, establecimiento o instalación militar, por lugares o sitios que no estén destinados para ello.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '51. Entrar o salir de la unidad, establecimiento o instalación militar, cuando los accesos se encuentren cerrados siempre que no tenga autorización correspondiente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '52. La permanencia no autorizada y sin justificación fuera de la unidad, establecimiento o instalación militar, donde preste servicio.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '53. Excederse en los lapsos de los permisos o licencias sin justificación. ');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '54. Realizar acrobacias aéreas sobre zonas pobladas o prohibidas, sin autorización, con aeronaves militares o civiles.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '55. En los casos de exhibición aérea, de concursos acrobáticos o de conmemoraciones de fechas patrias, ejecutar pruebas de acrobacia fuera de las áreas señaladas para al fin.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '56. Permitir que personas no autorizadas, aborden o piloteen aeronaves, naves o vehículos millares.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '57. Ordenar o utilizar vuelos autorizados, para asuntos de carácter particular.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '58. Realizar vuelos sin la autorización respectiva.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '59. Realizar vuelos sobre centros urbanos o poblados a baja altura, sin autorización, salvo en caso de aterrizaje de emergencia o forzoso.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '60. No observar los aviadores las reglas de pista o tráfico aéreo vigentes en los aeropuertos, helipuertos o aeródromos militares o civiles.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '61. Realizar maniobras navales en zonas prohibidas.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '62. No observar las normas de disciplina de vuelo y navegación marítima.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '63. Navegar en proximidades de playas y zonas costeras con afluencia de personas, sin causa justificada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '64. Ordenar, permitir o utilizar vehículos, aeronaves y embarcaciones militares, para fines de carácter particular.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '65. Traspasar límites fronterizos internacionales, sin la debida autorización.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '66. No observar las reglas de trafico naval en los puertos millares o civiles.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '67. Navegar en los ríos, lagos o represas a velocidades no permitidas, sin causa justificada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '68. Desacatar a la autoridad civil competente.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '69. irrespetar a los miembros de la Justicia militar o censurar en público sus actos o decisiones.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '70. Censurar los actos de servicio de sus superiores, en forma pública, procurando desacreditarlos.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '71. Manifestar públicamente opiniones que entrañen perjuicio a los intereses del país.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '72. Proferir expresiones perjudiciales en contra de las Leyes, Decretos, Resoluciones o medidas dictadas por cualquier autoridad legalmente constituida y de las disposiciones o funcionamiento de las Instituciones del Estado.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '73. Toda acción para ocultar o desviar la responsabilidad personal, que pudiera haber ocasionado la falta cometida.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '74. Participar en actos de propaganda, militancia o proselitismo político.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '75. Incitar a los subalternos o subalternas a participar en actos de propaganda, militancia o proselitismo político.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '76. Ofender, desafiar o provocar al o la superior, compañeros, compañeras, subalternos o subalternas.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '77. Extraviar el arma asignada.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '78. Ofender la moral y las buenas costumbres por medio de palabras gestos o actos.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '79. Establecer disputa o riña con sus superiores, compañeros, compañeras, subalternos o subalternas.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '80. Irrespetar los símbolos patrios.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '81. Hacer uso de canales irregulares o medios ilegítimos para elevar peticiones relativas al servicio de su situación dentro de la institución militar o asuntos particulares.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '82. Parcializarse al imponer una medida disciplinaria.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '83. No presentarse a la autoridad competente al término de una comisión, destacamento comisión de estudios en el país o en el exterior. ');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '84. Utilizar vehículos tácticos naves o aeronaves pertenecientes a la Fuerza Armada Nacional Bolivariana sin la debida autorización.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '85. Entrar o salir de la unidad, establecimiento o instalación militar, con efectivos militares, sin la autorización respectiva.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '86. Causar con base a sus conocimientos tácticos daños graves a material o equipo perteneciente o asignado a la Fuerza Armada Nacional Bolivariana.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '87. Participar en espectáculos públicos, en centros nocturnos o sitios de dudosa reputación.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '88. Extralimitarse en la aplicación de las medidas disciplinarias.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '89. Simular enfermedad o dolencia para evadir el cumplimiento de sus obligaciones.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '90. Retirarse el o la superior, compañero, compañera, subalterno o subalterna, en forma incorrecta o intentar desacreditarlo o desacreditarla ante otros u otras militares o civiles.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '91. No presentarse al o a la oficial jefe o jefa de guardia en la hora y en el uniforme correspondiente, encontrándose cumpliendo una medida disciplinaria.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '92. Desatender intencionalmente los asuntos del servicio con el propósito de obtener beneficios propios o facilitar el de terceros.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '93. Ingerir bebidas alcohólicas durante el cumplimiento de una medida disciplinaria.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '94. El o la militar que, llamado o llamada por el o la superior al orden, reprendido o reprendida, castigado o castigada, replique o aduzca razones ajenas al sentimiento que debe causarle su falta y al respeto con que debe oír a quien trata de corregirlo.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '95. Apropiarse de cualquier forma de dinero o bienes que no le pertenezcan.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '96. Realizarse modificaciones o alteraciones en cualquier parte del cuerpo, tales como perforaciones, tatuajes, cambios en el color del cabello exagerado, uso de lentes de contacto cosméticos.');
INSERT INTO `aparte_nieto` (`id_articulo_hijo`, `aparte_nieto`) VALUES ('3', '97. Utilizar placas militares en vehículos no autorizados.');
